package com.aditya.day13.restaurant; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/restaurants") public class RestaurantController{final RestaurantRepo r;final MenuRepo m;RestaurantController(RestaurantRepo r,MenuRepo m){this.r=r;this.m=m;}@PostMapping public Restaurant create(@RequestBody Restaurant x){return r.save(x);}@GetMapping public List<Restaurant> all(){return r.findAll();}@PostMapping("/{id}/menu")public MenuItem add(@PathVariable UUID id,@RequestBody MenuItem x){x.setRestaurantId(id);return m.save(x);}@GetMapping("/{id}/menu")public List<MenuItem> menu(@PathVariable UUID id){return m.findByRestaurantId(id);}}